import * as THREE from './vendor/three.module.js';
import {createLightHorse,LIGHT_ATLAS} from './horse-light-model.js';
import {createModelPaint,MODEL_PAINT} from './horse-model-paint.js';
import {createWeaponModel,WEAPON_MODELS} from './weapon-models.js';
import {GAME_CAMERA} from './hybrid-world.js';
import {unitArt} from './red-hats-art.js';
import {alphaBounds,rigidSpriteVertex} from './hybrid-sprites.js';
const $=id=>document.getElementById(id),host=$('scene'),renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x383838);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;host.append(renderer.domElement);
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera();scene.add(new THREE.HemisphereLight(0xfff9ec,0x737775,2));const light=new THREE.DirectionalLight(0xfff2dc,2.3);light.position.set(3,5,4);scene.add(light);const fill=new THREE.DirectionalLight(0xffffff,.7);fill.position.set(-2,2,-3);scene.add(fill);
const loader=new THREE.TextureLoader(),atlas=await loader.loadAsync(LIGHT_ATLAS);atlas.colorSpace=THREE.SRGBColorSpace;
const horse=createLightHorse(await(await fetch('./horse-10k-data.json')).json(),atlas);scene.add(horse.root);const paint=createModelPaint(renderer,horse,await loader.loadAsync(MODEL_PAINT));for(const part of horse.parts)part.material=paint.material;
const sprites=new Map();
for(const [id,info] of Object.entries(WEAPON_MODELS)){const option=document.createElement('option');option.value=id;option.textContent=info.label;$('weapon').append(option);}
let asset=null,currentSprite=null,markers=null,ppu=58;
function makeMarkers(){const group=new THREE.Group();for(const name of ['grip','support','muzzle','tip','release']){const target=asset.anchors[name];if(!target)continue;const marker=new THREE.Mesh(new THREE.SphereGeometry(.014,8,6),new THREE.MeshBasicMaterial({color:name==='muzzle'?0xff7744:0x55ff99,depthTest:false}));marker.userData.target=target;marker.renderOrder=10;group.add(marker);}scene.add(group);return group;}
async function spriteFor(id){if(sprites.has(id))return sprites.get(id);const art=unitArt({species:'horse',outfit:'normal',weapon:id,stance:'standing'}),texture=await loader.loadAsync(art.src);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=texture.magFilter=THREE.NearestFilter;texture.generateMipmaps=false;const canvas=document.createElement('canvas');canvas.width=art.width;canvas.height=art.height;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(texture.image,0,0);const bounds=alphaBounds(context.getImageData(0,0,art.width,art.height).data,art.width,art.height),sprite=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:texture,alphaTest:.4,toneMapped:false,side:THREE.DoubleSide}));const p=sprite.geometry.attributes.position,uv=sprite.geometry.attributes.uv;for(let i=0;i<p.count;i++)p.setXYZ(i,...rigidSpriteVertex({heading:0},art,bounds,uv.getX(i)*art.width,(1-uv.getY(i))*art.height,GAME_CAMERA));sprite.geometry.computeBoundingSphere();sprite.visible=false;scene.add(sprite);sprites.set(id,sprite);return sprite;}
let selection=0;
async function choose(){const ticket=++selection,id=$('weapon').value;$('error').textContent='';try{const sprite=await spriteFor(id);if(ticket!==selection)return;currentSprite=sprite;const old=asset;asset=createWeaponModel(id,atlas);horse.equipWeapon(asset);old?.dispose();if(markers){markers.removeFromParent();for(const m of markers.children){m.geometry.dispose();m.material.dispose();}}markers=makeMarkers();render();window.weaponReady=true;}catch(error){$('error').textContent=error.message;throw error;}}
function render(){if(!asset)return;const close=$('close').checked,alone=$('mode').value==='weapon';host.style.height=close?'620px':'270px';host.style.width=close?'min(1100px,100%)':'min(660px,100%)';$('labels').style.maxWidth=close?'1100px':'660px';const width=host.clientWidth,height=host.clientHeight;renderer.setSize(width,height);horse.pose('carry',+$('heading').value);for(const part of horse.parts)part.visible=!alone;for(const part of asset.parts)part.material.wireframe=$('wire').checked;paint.material.wireframe=$('wire').checked;
 for(const m of markers.children)m.position.copy(m.userData.target.getWorldPosition(new THREE.Vector3()));renderer.setScissorTest(true);
 for(let panel=0;panel<2;panel++){for(const sprite of sprites.values())sprite.visible=false;horse.root.visible=panel===1;markers.visible=panel===1&&$('contacts').checked;let focus=new THREE.Vector3(0,.84,0);ppu=close?300:58;if(panel===0)currentSprite.visible=true;else if(alone&&asset.id!=='hands'){const box=new THREE.Box3().setFromObject(asset.root);if(asset.mount)box.union(new THREE.Box3().setFromObject(asset.mount));focus=box.getCenter(new THREE.Vector3());const size=box.getSize(new THREE.Vector3());ppu=Math.min(1400,Math.min(width/2,height)*.78/Math.max(size.x,size.y,size.z,.15));}
 camera.left=-width/2/ppu/2;camera.right=width/2/ppu/2;camera.top=height/ppu/2;camera.bottom=-height/ppu/2;camera.near=.1;camera.far=30;const {azimuth:a,elevation:e}=GAME_CAMERA;camera.position.copy(focus).add(new THREE.Vector3(Math.sin(a)*Math.cos(e),Math.sin(e),Math.cos(a)*Math.cos(e)).multiplyScalar(5));camera.lookAt(focus);camera.updateProjectionMatrix();currentSprite.quaternion.copy(camera.quaternion);renderer.setViewport(panel*width/2,0,width/2,height);renderer.setScissor(panel*width/2,0,width/2,height);renderer.render(scene,camera);}
 renderer.setScissorTest(false);horse.root.visible=true;currentSprite.visible=false;const d=horse.diagnostics();$('model-label').textContent=alone?'INDEPENDENT WEAPON ASSET':'3D CARRY STUDY';$('status').textContent=`${asset.label} · ${asset.triangles.toLocaleString()} weapon triangles · ${asset.carry.hands.length} hand contacts · ${alone?'Fit to view':(close?300:58)+' CSS px/unit'}`;window.weaponAsset=asset;
}
$('weapon').addEventListener('change',choose);for(const id of ['close','mode','wire','contacts','heading'])$(id).addEventListener('input',render);new ResizeObserver(render).observe(host);
$('weapon').value=new URLSearchParams(location.search).get('weapon')||'rifle';if(!WEAPON_MODELS[$('weapon').value])$('weapon').value='rifle';await choose();
window.weaponHorse=horse;window.weaponDiagnostics=()=>({...horse.diagnostics(),pixelsPerUnit:ppu,view:$('mode').value,heading:+$('heading').value,triangles:asset.triangles,mountVisible:!!asset.mount?.visible,hoseVisible:!!asset.hose?.visible,geometries:renderer.info.memory.geometries});
